from pathlib import Path
import json, re, shutil, math, struct, zlib
root=Path(__file__).resolve().parents[1]
out=root/'outputs/ams-miniprogram'
def write(name,text):
 p=out/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def jsn(name,obj):write(name,json.dumps(obj,ensure_ascii=False,indent=2))
# Small original line icons for native tabBar (PNG required by the platform).
def icon(name,paths,color):
 size=48;pixels=[];rgb=tuple(int(color[i:i+2],16) for i in (1,3,5))
 for y in range(size):
  row=bytearray([0])
  for x in range(size):
   hits=0
   for sx,sy in [(0.25,0.25),(0.75,0.25),(0.25,0.75),(0.75,0.75)]:
    px,py=(x+sx)/2,(y+sy)/2;found=False
    for points in paths:
     for a,b in zip(points,points[1:]):
      dx,dy=b[0]-a[0],b[1]-a[1];u=max(0,min(1,((px-a[0])*dx+(py-a[1])*dy)/(dx*dx+dy*dy or 1)))
      if math.hypot(px-a[0]-u*dx,py-a[1]-u*dy)<0.85:found=True;break
     if found:break
    hits+=found
   row.extend((*rgb,round(hits*255/4)))
  pixels.append(row)
 def chunk(kind,payload):return struct.pack('>I',len(payload))+kind+payload+struct.pack('>I',zlib.crc32(kind+payload)&0xffffffff)
 png=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',size,size,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(b''.join(pixels)))+chunk(b'IEND',b'')
 p=out/('assets/'+name+'.png');p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(png)
def circle(x,y,r):return [(x+math.cos(i*math.pi/16)*r,y+math.sin(i*math.pi/16)*r) for i in range(33)]
icons={'today':[[(4,5),(20,5),(20,21),(4,21),(4,5)],[(8,3),(8,7)],[(16,3),(16,7)],[(4,10),(20,10)],[(8,14),(11,14)],[(14,14),(17,14)]],
 'records':[[(6,3),(18,3),(18,21),(6,21),(6,3)],[(9,8),(15,8)],[(9,12),(15,12)],[(9,16),(13,16)]],
 'leave':[circle(9,7,3.5),[(3,21),(3,18),(5,14),(9,12),(13,14)],[(15,13),(19,17),(15,21)],[(12,17),(22,17)]],
 'reservations':[[(4,5),(20,5),(20,21),(4,21),(4,5)],[(8,3),(8,7)],[(16,3),(16,7)],[(4,10),(20,10)],[(8,15),(11,18),(17,13)]]}
for name,paths in icons.items():
 icon(name,paths,'#69758a');icon(name+'-active',paths,'#172e61');icon(name+'-dark',paths,'#eef2f7')
