write('services/mobile-bridge.js',"const amsLogin=require('./ams-login'),portalSso=require('./portal-sso'),diag=require('./diagnostics');const tests=[{id:'A14'},{id:'A04'}];module.exports={\n"+ams.replace('wx.request(', 'this.request(')+flow.replace('wx.request(', 'this.request(')+"};\n")
write('services/session.js',r'''
const bridge=require('./mobile-bridge'),portal=require('./portal-sso');
const AMS='https://ams.xjtlu.edu.cn/xjtlu',PORTAL=portal.PORTAL;
let generation=0,session={credentials:{},fields:{}},tasks=new Set();
function clear(reason='logout'){generation++;tasks.forEach(t=>t.abort());tasks.clear();session={credentials:{},fields:{}};if(typeof getApp==='function'&&getApp().recordSessionEvent)getApp().recordSessionEvent('session-clear-'+reason);}
function request(options){const epoch=generation;return new Promise((resolve,reject)=>{let task;const done=()=>{if(task)tasks.delete(task)};task=wx.request({...options,timeout:15000,success:r=>{done();if(epoch!==generation)return reject(Error('会话已改变'));resolve(r)},fail:()=>{done();reject(Error('网络请求未完成，请检查网络后重试'))}});tasks.add(task);});}
function parse(r,kind){let b=r.data;if(typeof b==='string'){try{b=JSON.parse(b)}catch(e){throw Error('学校返回了非数据页面，请重新登录')}}if(r.statusCode!==200||!b||(kind==='portal'?b.success!==true:String(b.code)!=='0')){if(r.statusCode===401||r.statusCode===403||b&&['401','403'].includes(String(b.code))){if(kind!=='portal')clear('school-rejected');throw Error('学校会话已失效，请重新登录')}throw Error('学校未接受本次请求，请检查输入或稍后重试')}return b.data;}
async function captcha(){return parse(await request({url:PORTAL+'/api/authentication/getCaptcha'}),'portal');}
async function login(fields,onStage){clear('login-start');const epoch=generation;onStage('正在验证学校账号');const data=parse(await request({url:PORTAL+'/api/authentication/loginByOtp',method:'POST',data:{username:fields.username.trim(),equipNo:'amswx-'+Date.now()+'-'+Math.random().toString(36).slice(2),mobileSystem:wx.getDeviceInfo().platform==='ios'?'ios':'android',captchaKey:fields.captchaKey,code:fields.imageCode.trim(),loginCode:fields.otp.trim()}}),'portal');if(!data||!data.token)throw Error('学校没有返回登录会话');const credentials={portal:data.token,...portal.session(data)};const context={...bridge,request(options){if(epoch!==generation)throw Error('会话已改变');let task;const done=()=>{if(task)tasks.delete(task)};task=wx.request({...options,success:r=>{done();if(epoch!==generation){options.fail({});return;}options.success(r)},fail:e=>{done();options.fail(e)}});tasks.add(task);return task;},data:{busy:false,fields:{}},credentials,amsJar:{},setData(update){for(const [k,v]of Object.entries(update)){if(k.startsWith('fields.'))this.data.fields[k.slice(7)]=v;else this.data[k]=v;}},confirm:async()=>true,sync(){},record(t,result){this.last=result;},amsFailure(){this.last={label:'接续失败'};},execute:async()=>{}};
onStage('正在连接学校考勤');await context.portalAmsFlow();if(epoch!==generation)throw Error('会话已改变');if(!credentials.ams){session={credentials,fields:{}};throw Error('学校账号已验证，考勤连接未完成。请稍后重试登录')}session={credentials,fields:context.data.fields,account:fields.username.trim()};return true;}
async function read(path,params={}){if(!session.credentials.ams)throw Error('请先登录学校账号');return parse(await request({url:AMS+path,method:'GET',data:params,header:{'X-Token':session.credentials.ams}}),'ams');}
function term(){const f=session.fields;if(!f.academicYear||!f.semester)throw Error('学校未返回学年学期，无法读取课程记录');return {academicYear:f.academicYear,semester:f.semester};}
module.exports={captcha,login,clear,revision:()=>generation,authenticated:()=>!!session.credentials.ams,account:()=>session.account||'',timetable:()=>read('/xjtlu-base-student-timetables/getStudentTimetable'),courses:()=>read('/stuapi/my-module/list',{...term(),moudleTitle:'',type:'1'}),leaves:()=>read('/stuapi/xjtlu-leave/getLeaveList'),detail:(moduleCode,pageNum)=>{const q={...term(),moduleCode,pageNum:String(pageNum),pageSize:'10'};return read('/stuapi/my-module/recordList?'+Object.keys(q).map(k=>k+'='+encodeURIComponent(q[k])).join('&'));}};
''')
write('utils/timetable.js',r'''
function dayKey(now){return String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');}
function offset(value,now){const m=String(value||'').match(/^(?:(\d{4})-)?(\d{2})-(\d{2})$/);if(!m)return null;let year=m[1]?Number(m[1]):now.getFullYear();if(!m[1]&&now.getMonth()===11&&Number(m[2])===1)year++;if(!m[1]&&now.getMonth()===0&&Number(m[2])===12)year--;const d=new Date(year,Number(m[2])-1,Number(m[3]));if(d.getMonth()+1!==Number(m[2])||d.getDate()!==Number(m[3]))return null;return Math.round((Date.UTC(year,Number(m[2])-1,Number(m[3]))-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);}
function course(c,now,today){const match=String(c.moduleTime||'').match(/\d{1,2}:\d{2}/g)||[];const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);let start=match.length>=2?mins(match[0]):NaN,end=match.length>=2?mins(match[1])-10:NaN;if(start<0||start>=1440||end<=start||end>=1440||match.some(t=>Number(t.split(':')[1])>=60)){start=NaN;end=NaN;}const n=now.getHours()*60+now.getMinutes(),valid=Number.isFinite(start)&&Number.isFinite(end);return {...c,moduleTitle:c.moduleTitle||'未命名课程',room:c.room||'地点待确认',start:valid?match[0]:'—',end:valid?String(Math.floor(end/60)).padStart(2,'0')+':'+String(end%60).padStart(2,'0'):'',sort:valid?start:9999,ended:valid&&today&&n>=end,active:valid&&today&&n>=start&&n<end,state:!valid?'时间待确认':today&&n>=end?'已结束':today&&n>=start?'进行中':'待上课',minutes:valid?Math.max(0,(n>=start?end:start)-n):null};}
function view(raw,selected,now=new Date()){if(!Array.isArray(raw))throw Error('课表数据格式未识别');let days=raw.filter(d=>d&&offset(d.date,now)!==null&&Array.isArray(d.timetableVoList)).map(d=>({...d,offset:offset(d.date,now)}));if(raw.length&&!days.length)throw Error('学校返回的课程日期无法识别');days=days.filter(d=>d.offset>=0).sort((a,b)=>a.offset-b.offset);if(raw.length&&!days.length)throw Error('课表日期已过期，请重新读取');if(!days.length||days.every(d=>d.offset>0))days.unshift({date:dayKey(now),offset:0,timetableVoList:[]});days=days.map(d=>({...d,label:d.offset===0?'今天':d.offset===1?'明天':d.offset===2?'后天':['周日','周一','周二','周三','周四','周五','周六'][(now.getDay()+d.offset)%7]}));let index=days.findIndex(d=>d.date===selected);if(index<0)index=Math.max(0,days.findIndex(d=>d.offset===0));const current=days[index],list=current.timetableVoList.map(c=>course(c,now,current.offset===0)).sort((a,b)=>a.sort-b.sort);const ended=list.filter(c=>c.ended||current.offset<0),remaining=list.filter(c=>!ended.includes(c)),focus=remaining.find(c=>c.start!=='—');return {days,selected:current.date,remaining,ended,focus:focus||null,count:list.length,month:now.getFullYear()+' 年 '+(now.getMonth()+1)+' 月',focusLabel:focus&&focus.active?'正在上课':current.offset===0?'下一节课':'当天第一节课',today:current.offset===0};}
module.exports={view,offset,course};
''')
