write('pages/login/index.js',r'''
// School session is owned by App, shared by pages and components.
Page({data:{username:'',imageCode:'',otp:'',captcha:'',busy:false,error:'',stage:''},onUnload(){getApp().recordSessionEvent(this.completed?'login-unload-success':'login-unload-incomplete');this.gone=true;if(this.data.busy&&!this.completed)getApp().sessionService.clear();this.captchaKey='';this.setData({username:'',imageCode:'',otp:'',captcha:''});},input(e){this.setData({[e.currentTarget.dataset.key]:e.detail.value});},async refreshCaptcha(){if(this.data.busy)return;this.setData({busy:true,error:'',imageCode:'',captcha:''});this.captchaKey='';try{const r=await getApp().sessionService.captcha();if(this.gone)return;if(!r||typeof r.imageBase!=='string'||!r.captchaKey)throw Error('学校未返回图片验证码');this.captchaKey=r.captchaKey;this.setData({captcha:r.imageBase.startsWith('data:image/')?r.imageBase:'data:image/png;base64,'+r.imageBase});}catch(e){if(!this.gone)this.setData({error:e.message});}finally{if(!this.gone)this.setData({busy:false});}},async submit(){if(this.data.busy)return;const f=this.data;if(!f.username.trim()||!f.imageCode.trim()||!f.otp.trim()||!this.captchaKey){this.setData({error:'请获取图片验证码并填写账号、图片验证码和动态码'});return;}this.setData({busy:true,error:''});try{await getApp().sessionService.login({...f,captchaKey:this.captchaKey},stage=>{if(!this.gone)this.setData({stage})});getApp().recordSessionEvent('login-complete');if(!this.gone){if(!getApp().sessionService.authenticated())throw Error('学校考勤会话尚未建立，请重新登录');this.completed=true;await new Promise((resolve,reject)=>wx.switchTab({url:'/pages/today/index',success:resolve,fail:()=>reject(Error('已登录，但返回课表未完成。请返回课表或重新打开小程序。'))}));}}catch(e){if(!this.gone)this.setData({error:e.message});}finally{this.captchaKey='';if(!this.gone)this.setData({busy:false,otp:'',imageCode:'',captcha:'',stage:''});}}});
''')
write('pages/login/index.wxml',r'''<view class="login"><text class="eyebrow">XJTLU / CAMPUS DAY</text><view class="title">学校账号登录</view><view class="help">通过学校动态码验证身份，连接课程与考勤记录。</view><view class="form"><label>学校账号</label><input value="{{username}}" data-key="username" bindinput="input" placeholder="填写学校账号" disabled="{{busy}}"/><label>图片验证码</label><view class="captcha-row"><image wx:if="captcha" src="{{captcha}}" mode="aspectFit"/><button bindtap="refreshCaptcha" disabled="{{busy}}">{{captcha?'换一张':'获取图片验证码'}}</button></view><input value="{{imageCode}}" data-key="imageCode" bindinput="input" placeholder="输入图片中的字符" disabled="{{busy}}"/><label>动态码（OTP）</label><input value="{{otp}}" data-key="otp" bindinput="input" type="number" password placeholder="填写认证器当前动态码" disabled="{{busy}}"/></view><view wx:if="error" class="error">{{error}}</view><button class="submit" bindtap="submit" disabled="{{busy}}">{{busy?(stage||'正在读取…'):'登录并连接考勤'}}</button><view class="help">仅在当前运行会话保留学校凭证，退出后清除。小程序被微信回收后可能需要重新登录。不保存账号或验证码。</view></view>''')
